// n8n 2.x: Code node isolado (task runner) - JS puro, sem env vars nem require.
// Reconciliacao BIDIRECIONAL por protocolo entre Splitters (massiva_history) e Voalle (Elleven).
// So propagamos FECHAMENTO/CANCELAMENTO; nunca reabrimos.
//
// Direcao 1 (Splitters -> Voalle): Splitters ja encerrou (status='encerrada') e Voalle ainda aberto
//   -> fecha o chamado no Voalle (Elleven). Se o Voalle teve acao MAIS RECENTE que o fechamento no
//   Splitters, marcamos 'revisar_manual' em vez de fechar (nao reabrimos, mas tambem nao fechamos
//   as cegas por cima de uma acao recente do lado aberto).
//
// Direcao 2 (Voalle -> Splitters, NOVO): Splitters ainda esta 'aberta' mas o Elleven ja mostra
//   'Encerrado' ou 'Cancelado' para o mesmo protocolo -> espelha esse status no Splitters
//   (massiva_history), chamando /encerrar ou /cancelar conforme o status real do Elleven.

function unwrap(resp) {
  if (Array.isArray(resp)) return resp;
  if (resp && Array.isArray(resp.data)) return resp.data;
  return [];
}
function ts(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.getTime();
}

const elleven = unwrap($('GET Elleven2').first().json);
const hist = unwrap($('GET History (Splitters)2').first().json);
const limit = Number($('Config2').item.json.limit) || 0;

const ellevenByProto = new Map();
for (const e of elleven) {
  if (e && e.protocolo != null) ellevenByProto.set(String(e.protocolo), e);
}

const itens = [];
for (const h of hist) {
  if (!h || h.protocolo == null) continue;
  const proto = String(h.protocolo);
  const e = ellevenByProto.get(proto);
  if (!e) continue; // so reconcilia o que existe nos dois lados

  const splittersAberta = h.status === 'aberta';
  const splittersEncerrada = h.status === 'encerrada';
  // status string do Elleven (t2.title no gateway): 'Encerrado' | 'Cancelado' | outros (aberto/em andamento)
  const ellevenEncerrado = e.status === 'Encerrado';
  const ellevenCancelado = e.status === 'Cancelado';
  const voalleClosed = !!e.finalizado;

  const assignmentId = h.assignmentId != null ? String(h.assignmentId) : '';
  let acao = null;
  let motivoRevisao = null;

  if (splittersEncerrada && !voalleClosed) {
    // Direcao 1: Splitters fechou; Voalle aberto.
    if (!h.assignmentId) continue;
    const tSplitters = ts(h.ultimaAcaoEm);
    const tVoalle = ts(e.criacao);
    if (tSplitters != null && tVoalle != null && tVoalle > tSplitters) {
      acao = 'revisar_manual';
      motivoRevisao = 'Voalle (aberto) teve acao mais recente (' + e.criacao + ') que o fechamento no Splitters (' + h.ultimaAcaoEm + ').';
    } else {
      acao = 'fechar_voalle';
    }
  } else if (splittersAberta && (ellevenEncerrado || ellevenCancelado)) {
    // Direcao 2 (nova): Splitters ainda aberta; Elleven ja encerrado/cancelado.
    // So estamos espelhando o status final do Elleven (fonte da verdade); nunca reabrimos.
    acao = ellevenEncerrado ? 'encerrar_splitters' : 'cancelar_splitters';
  } else {
    continue; // em sincronia ou nenhuma das duas direcoes se aplica
  }

  itens.push({
    json: {
      protocolo: proto,
      assignmentId: assignmentId,
      acao: acao,
      motivoRevisao: motivoRevisao,
      statusSplitters: h.status,
      statusElleven: e.status,
      ultimaAcaoSplitters: h.ultimaAcaoEm,
      finalizadoVoalle: e.finalizado || null,
      body: {
        assignmentId: assignmentId,
        incidentStatusId: '4',
        description: 'Encerramento automatico via reconciliacao n8n (Splitters x Voalle). Protocolo ' + proto + ' encerrado no Splitters em ' + (h.ultimaAcaoEm || 'N/D') + ' e ainda aberto no Voalle. Fonte da verdade: ultima acao = Splitters.',
        progress: '0',
        priority: '35',
        notificationTarget: '0',
        privateReport: 'true'
      },
      bodySplittersEncerrar: {
        closedBy: 'reconciliacao-n8n',
        closeDescription: 'Encerrado via reconciliacao automatica. Elleven ja estava com status \'Encerrado\' para o protocolo ' + proto + '.'
      },
      bodySplittersCancelar: {
        cancelledBy: 'reconciliacao-n8n',
        cancelDescription: 'Cancelado via reconciliacao automatica. Elleven ja estava com status \'Cancelado\' para o protocolo ' + proto + '.'
      }
    }
  });
}

return limit > 0 ? itens.slice(0, limit) : itens;

// Roda 1x por item. Usa pairedItem (via $('Reconciliar (diff)2')) para recuperar o item de origem,
// independentemente do caminho (DELETE/PATCH ou revisar_manual direto).
const src = $('Reconciliar (diff)2').item.json;
const proto = src.protocolo;
const assignmentId = src.assignmentId;
const acao = src.acao;

let categoria;
let motivo = '';

if (acao === 'revisar_manual') {
  categoria = 'revisar';
  motivo = src.motivoRevisao || 'Divergencia que requer revisao manual (nunca reabrir automaticamente).';
} else {
  const j = $json;
  if (j && j.error) {
    categoria = 'falha';
    const msg = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
    motivo = 'Erro de transporte: ' + msg;
  } else {
    const status = j ? j.statusCode : undefined;
    const body = (j && j.body !== undefined) ? j.body : j;
    const httpOk = (status === undefined) || (status >= 200 && status < 300);
    const logicOk = body && body.success === true;
    if (httpOk && logicOk) {
      categoria = 'ok';
      motivo = acao === 'fechar_voalle'
        ? 'Fechado na Voalle (Elleven)'
        : (acao === 'encerrar_splitters' ? 'Encerrado no Splitters (massiva_history)' : 'Cancelado no Splitters (massiva_history)');
    } else {
      categoria = 'falha';
      motivo = 'HTTP ' + (status !== undefined ? status : '?');
      if (body && Array.isArray(body.messages) && body.messages.length) motivo += ' - ' + body.messages.map(m => m.message).join('; ');
      else if (body && body.message) motivo += ' - ' + body.message;
    }
  }
}

return { json: { protocolo: proto, assignmentId: assignmentId, acao: acao, categoria: categoria, motivo: motivo } };

// Agrega os resultados normalizados (1 por protocolo) e monta o e-mail.
const rows = $input.all().map(i => i.json);
const sucessos = rows.filter(r => r.categoria === 'ok');
const falhas = rows.filter(r => r.categoria === 'falha');
const revisar = rows.filter(r => r.categoria === 'revisar');
const temFalhas = falhas.length > 0 || revisar.length > 0;

function li(r) { return '<li>Protocolo <b>' + r.protocolo + '</b> [' + r.acao + ']: ' + r.motivo + '</li>'; }

const assunto = '[Reconciliacao Massivas] ' + sucessos.length + ' ok, ' + falhas.length + ' falha(s), ' + revisar.length + ' p/ revisao';
let corpoHtml = '<p>Reconciliacao bidirecional Splitters x Voalle (Elleven) concluida.</p>'
  + '<p><b>Sucessos:</b> ' + sucessos.length + ' &nbsp; <b>Falhas:</b> ' + falhas.length + ' &nbsp; <b>Revisao manual:</b> ' + revisar.length + '</p>';
if (falhas.length) corpoHtml += '<p><b>Falhas ao propagar fechamento/cancelamento:</b></p><ul>' + falhas.map(li).join('') + '</ul>';
if (revisar.length) corpoHtml += '<p><b>Requerem revisao manual (lado aberto com acao mais recente - nao reaberto automaticamente):</b></p><ul>' + revisar.map(li).join('') + '</ul>';
if (sucessos.length) corpoHtml += '<p>Sucessos: ' + sucessos.map(r => r.protocolo + ' (' + r.acao + ')').join(', ') + '</p>';

return [{ json: { temFalhas, total: rows.length, okCount: sucessos.length, falhaCount: falhas.length, revisarCount: revisar.length, sucessos, falhas, revisar, assunto, corpoHtml } }];
